'use strict'

import resource from '../resource'
import { directionOf, enemyReached, bladeCentre, REACH_BEAM, WEAPON_BEAM } from './enemies/common'
import { TILE_WIDTH, TILE_HEIGHT, NES_PIXEL } from '../constant'

// Measured in the ROM (object $0E): with all his hearts, Link's sword flies off as he thrusts it, 3 NES
// pixels a frame (6 display pixels a game step), changing palette every frame. It hits an enemy as hard
// as the sword. Out of the screen (state $11), it waits a frame and bursts into 4 sparks going away
// diagonally, 1 NES pixel a frame, for 22 frames
const SPEED = 6
const BURST_WAIT_STEPS = 1
const BURST_STEPS = 22
const SPARK_SPEED = 2
const SPARKS = [['north_west', -1, -1], ['north_east', 1, -1], ['south_west', -1, 1], ['south_east', 1, 1]]
// The spark is 8 NES pixels wide, 16 high
const SPARK_WIDTH = TILE_WIDTH / 2
const SIDEWAYS_BELOW = 3 * NES_PIXEL

export class SwordBeam {
  constructor (x, y, direction, [dx, dy], damage) {
    this.x = x
    this.y = y
    this.direction = direction
    this.dx = dx
    this.dy = dy
    this.damage = damage
    this.width = TILE_WIDTH
    this.height = TILE_HEIGHT
    this.steps = 0
    // Steps since it burst; undefined while it flies
    this.burstSteps = undefined
    this.done = false
  }

  get flying () {
    return this.burstSteps === undefined
  }

  // What hits the enemies: the blade, across the middle of its tile
  getBox () {
    const horizontal = this.dx !== 0
    return horizontal
      ? { x: this.x, y: this.y + TILE_HEIGHT / 4, width: TILE_WIDTH, height: TILE_HEIGHT / 2 }
      : { x: this.x + TILE_WIDTH / 4, y: this.y, width: TILE_WIDTH / 2, height: TILE_HEIGHT }
  }

  burst () {
    this.burstSteps = 0
  }

  process (map, link) {
    this.steps++
    if (!this.flying) {
      this.burstSteps++
      if (this.burstSteps >= BURST_WAIT_STEPS + BURST_STEPS) {
        this.done = true
      }
      return
    }
    this.x += this.dx * SPEED
    this.y += this.dy * SPEED
    const box = this.getBox()
    if (box.x < map.x || box.y < map.y || box.x + box.width > map.x + map.width || box.y + box.height > map.y + map.height) {
      this.burst()
      return
    }
    // Not measured: it bursts on the enemy it hits too
    const enemy = enemyReached(map, bladeCentre(this.x, this.y, link.direction ?? this.direction), REACH_BEAM)
    if (enemy) {
      enemy.hit(link, { damage: this.damage, direction: directionOf(enemy.x - this.x, enemy.y - this.y), weapon: WEAPON_BEAM })
      this.burst()
    }
  }

  draw (context) {
    if (this.flying) {
      // Sideways, its sprites 3 NES pixels below its place (measured)
      const below = this.dx !== 0 ? SIDEWAYS_BELOW : 0
      drawFrame(context, `sword_beam_${this.direction}`, this.steps, this.x, this.y + below, this.width, this.height)
      return
    }
    if (this.burstSteps <= BURST_WAIT_STEPS) {
      return
    }
    const distance = (this.burstSteps - BURST_WAIT_STEPS) * SPARK_SPEED
    const centerX = this.x + this.width / 2
    const centerY = this.y + this.height / 2
    for (const [name, sx, sy] of SPARKS) {
      const x = centerX + sx * distance - (sx < 0 ? SPARK_WIDTH : 0)
      const y = centerY + sy * distance - (sy < 0 ? this.height : 0)
      drawFrame(context, `sword_beam_spark_${name}`, this.steps, x, y, this.width, this.height)
    }
  }
}

function drawFrame (context, name, steps, x, y, width, height) {
  const images = resource.getSprite(name)?.images
  images?.[steps % images.length]?.draw(context, x, y, width, height)
}
