'use strict'

import { isBlocked, isBlockedByQuarters } from '../../service/collision'
import soundManager from '../../service/sound-manager'
import resource from '../../resource'
import { overlaps } from '../../utils/box'
import { chooseDrop, Drop } from '../drop'
import { isInRoom } from '../room-box'
import { NES_COLOURS } from '../resource/nes-colours'
import { TILE_WIDTH, TILE_HEIGHT, NES_PIXEL, DIRECTION_EAST, DIRECTION_NORTH, DIRECTION_SOUTH, DIRECTION_WEST, SOUND_ENNEMY_HIT, SOUND_ENNEMY_DIE } from '../../constant'

// Everything is counted in game steps (60 per second) and display pixels (twice the NES ones).
// The values follow the behaviour of the original game, measured by eye: they are approximations

export const DIRECTION_VECTORS = {
  [DIRECTION_EAST]: [1, 0],
  [DIRECTION_NORTH]: [0, -1],
  [DIRECTION_SOUTH]: [0, 1],
  [DIRECTION_WEST]: [-1, 0]
}
export const DIRECTIONS = Object.keys(DIRECTION_VECTORS)

export const CLOUD_FRAME_STEPS = 8
const ROOM_CLOUD_FRAMES = 6
export const DEATH_FRAME_STEPS = 6
// Hit, an enemy waits a frame, then is pushed back 4 NES pixels a frame for 16 frames, the way Link strikes, its
// own way whatever (measured in the ROM on moblins, octoroks, lynels); on the grid, the scenery ahead stops it as
// it stops the walkers (see canWalkTo)
export const KNOCKBACK_WAIT = 1
export const KNOCKBACK_STEPS = KNOCKBACK_WAIT + 16
export const KNOCKBACK_SPEED = 8
export const BODY_INSET = 4
export const TERRAIN_INSET = 2
// A boomerang stuns an enemy for 160 frames (measured in the ROM on a red octorok: $3D + slot)
export const STUN_STEPS = 160
// The wand held out hits as hard as the white sword ($20, bank 1 $B5D8)
const WAND_DAMAGE = 2

export const STATE_WAITING = 'waiting'
export const STATE_SPAWNING = 'spawning'
export const STATE_HURT = 'hurt'
export const STATE_DYING = 'dying'
export const STATE_DEAD = 'dead'

export function randomInt (random, min, max) {
  return min + Math.floor(random() * (max - min + 1))
}

export function pick (random, values) {
  return values[Math.floor(random() * values.length)]
}

export function shuffle (random, values) {
  const shuffled = [...values]
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(random() * (i + 1))
    ;[shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]]
  }

  return shuffled
}

// Whether a weapon reaches an enemy, as the ROM looks (bank 1, $B240 to $B695): the centre of the enemy (x + 8, or
// x + 4 for the narrow ones, bit $40 of $04BF: the gels; y + 8) is less than the thresholds away from the centre of
// the weapon, across and along ([x, y], NES pixels). The places are those of the objects of the ROM
export function reaches (enemy, centreX, centreY, [thresholdX, thresholdY]) {
  const x = enemy.x + (enemy.narrow ? 4 : 8) * NES_PIXEL
  const y = enemy.y + 8 * NES_PIXEL
  return Math.abs(x - centreX) < thresholdX * NES_PIXEL && Math.abs(y - centreY) < thresholdY * NES_PIXEL
}

// The centre of the sword, the wand, the flying sword, an arrow or the magic, as the ROM takes it from the way Link
// faces ($98): x + 6, y + 8 up or down, x + 8, y + 6 sideways
export function bladeCentre (x, y, direction) {
  const vertical = direction === DIRECTION_NORTH || direction === DIRECTION_SOUTH
  return vertical ? [x + 6 * NES_PIXEL, y + 8 * NES_PIXEL] : [x + 8 * NES_PIXEL, y + 6 * NES_PIXEL]
}

// The centre of a boomerang (x + 4, y + 8), of a bomb or a flame (x + 8, y + 8)
export const boomerangCentre = (x, y) => [x + 4 * NES_PIXEL, y + 8 * NES_PIXEL]
export const tileCentre = (x, y) => [x + 8 * NES_PIXEL, y + 8 * NES_PIXEL]

// The thresholds of each weapon ($0D, $0E): the sword and the wand held out 12 across the blade, 16 along it; the
// flying sword and the magic 12, an arrow 11, the boomerang 10, a bomb blowing up 24, a flame 14
export const REACH_BLADE_VERTICAL = [12, 16]
export const REACH_BLADE_SIDEWAYS = [16, 12]
export const REACH_BEAM = [12, 12]
export const REACH_ARROW = [11, 11]
export const REACH_BOOMERANG = [10, 10]
export const REACH_BOMB = [24, 24]
export const REACH_FLAME = [14, 14]

// What a hit is made with (hit: weapon), when an enemy minds it (the darknut's shield, see darknut.js): the sword held
// out by default
export const WEAPON_SWORD = 'sword'
export const WEAPON_WAND = 'wand'
export const WEAPON_BEAM = 'beam'
export const WEAPON_ARROW = 'arrow'
export const WEAPON_MAGIC = 'magic'
export const WEAPON_FLAME = 'flame'
export const WEAPON_BOMB = 'bomb'

// The first enemy of the screen a weapon reaches that can be hit
export function enemyReached (map, [centreX, centreY], thresholds) {
  return map.activeEnemies.find(enemy => enemy.isVulnerable && reaches(enemy, centreX, centreY, thresholds))
}

export function inset (x, y, width, height, value) {
  return { x: x + value, y: y + value, width: width - 2 * value, height: height - 2 * value }
}

export function isInside (map, x, y, width, height) {
  return map.x <= x && x + width <= map.x + map.width && map.y <= y && y + height <= map.y + map.height
}

// Free for a tile sized body (not in a wall, on the screen)
export function isFree (map, x, y) {
  return isInside(map, x, y, TILE_WIDTH, TILE_HEIGHT) && !isBlocked(map, inset(x, y, TILE_WIDTH, TILE_HEIGHT, TERRAIN_INSET))
}

// On the grid, the ROM looks at the scenery one tile ahead (bank 7, $EDFA), at quarters of it only: the bottom
// left one of the tile beside it, the bottom ones of the tile above, the top ones of the tile below. Then it
// goes the whole tile without looking again, brushing past the corners of the rocks. Quarters as [column, line]
const PROBES = {
  east: [[0, 1]],
  west: [[0, 1]],
  north: [[0, 1], [1, 1]],
  south: [[0, 0], [1, 0]]
}

// From a point of the grid, a body of a tile can go to the next tile that way: it is on the screen and its probed
// quarters are free (see PROBES)
export function canWalkTo (map, x, y, direction) {
  const [dx, dy] = DIRECTION_VECTORS[direction]
  const toX = x + dx * TILE_WIDTH
  const toY = y + dy * TILE_HEIGHT
  // In a dungeon, the enemies stay in the room, as Link (see room-box.js)
  if (!isInside(map, toX, toY, TILE_WIDTH, TILE_HEIGHT) || !isInRoom(map, toX, toY)) {
    return false
  }
  const quarter = { width: TILE_WIDTH / 2, height: TILE_HEIGHT / 2 }
  return PROBES[direction].every(([column, line]) => !isBlockedByQuarters(map, { ...quarter, x: toX + column * quarter.width, y: toY + line * quarter.height }))
}

// An enemy hit changes palette (measured on a Stalfos of $74, level 1): $04F0 + slot starts at $10 and goes down by
// 1 every 2 frames; while it is not 0, its sprites take the palette of its 2 low bits: 0 (Link's), 3, 2, 1. Sprite
// palette 3 is that of the place (bank 6 $A27E at the surface; the background palette 2 of a level)
export const FLASH_STEPS = 32
const FLASH_PALETTES = [
  ['29', '27', '17'],
  ['02', '22', '30'],
  ['16', '27', '30']
]
const SPRITE_PALETTE_3 = {
  world: ['0f', '1c', '16'],
  level1: ['0c', '1c', '2c'],
  level2: ['02', '12', '22'],
  level3: ['0b', '1b', '2b'],
  level4: ['0f', '18', '28']
}
// The palette being drawn (see Enemy.draw)
let flashing

// The counter of the ROM in its RAM ($04F0 + slot) from the steps left since the hit (FLASH_STEPS at the hit): $10,
// then $0F from the frame after, 1 less every 2 frames, 0 the 31st frame (measured). The sprites show it a frame
// later (see flashColours)
export function hitCounter (flashSteps) {
  return flashSteps > 0 ? Math.floor(flashSteps / 2) : 0
}

// The colours of the sprite palette of the ROM a hit enemy has this step (undefined when it has its own)
export function flashColours (flashSteps, type) {
  // Never hit (undefined) or no longer
  if (!(flashSteps > 0)) {
    return undefined
  }
  const palette = Math.ceil(flashSteps / 2) & 3
  const codes = palette === 3 ? SPRITE_PALETTE_3[type] ?? SPRITE_PALETTE_3.world : FLASH_PALETTES[palette]
  return codes.map(code => NES_COLOURS[parseInt(code, 16)])
}

// An image in these colours (the 3 of a sprite palette), or as it is
function inColours (image, colours) {
  if (!image || !colours || !image.palette) {
    return image
  }
  return resource.recolourImage(image, `flash:${colours.join('')}`, () => new Map(image.palette.slice(1).map((colour, i) => [colour, colours[i]]).filter(([colour]) => colour)))
}

// An image of something hit (an old man too), in the palette of the ROM of this step
export function flashImage (image, flashSteps, type) {
  return inColours(image, flashColours(flashSteps, type))
}

export function drawImage (context, sprite, index, x, y, width, height) {
  inColours(sprite?.images[index], flashing)?.draw(context, x, y, width, height)
}

// The cardinal direction closest to a vector
export function directionOf (dx, dy) {
  if (Math.abs(dx) >= Math.abs(dy)) {
    return dx >= 0 ? DIRECTION_EAST : DIRECTION_WEST
  }
  return dy >= 0 ? DIRECTION_SOUTH : DIRECTION_NORTH
}

// What all enemies share: appearing in a cloud, being hit by the sword (pushed back, then dying),
// hurting Link on contact. A kind of enemy says what it does the rest of the time (act) and how it
// looks (drawBody); while hurt, it goes back to `resumeState` afterwards
export class Enemy {
  constructor (type, x, y, { life, contactDamage }, random = Math.random) {
    this.type = type
    this.x = x
    this.y = y
    this.width = TILE_WIDTH
    this.height = TILE_HEIGHT
    this.life = life
    this.contactDamage = contactDamage
    this.random = random

    this.state = undefined
    this.steps = 0 // In the current state
    this.resumeState = undefined
    this.knockbackDirection = undefined
    this.lastSwing = undefined
    this.drop = undefined // What it leaves when dead
    this.stunSteps = 0
    this.slot = undefined // Its place among the objects of a room of a dungeon (1 to 11), as in the ROM
  }

  get isDead () {
    return this.state === STATE_DEAD
  }

  // A room is cleared when they are all dead (the blade traps do not count)
  get mustDie () {
    return true
  }

  // Hurts Link when touching him
  get isActive () {
    return ![STATE_WAITING, STATE_SPAWNING, STATE_DYING, STATE_DEAD].includes(this.state)
  }

  // Can be hit by the sword. Hit, not again while its counter is not 0 (bank 1 $B720): the first hit that lands is 31
  // frames after (measured on a Stalfos of $74, level 1), well after its knockback
  get isVulnerable () {
    return this.isActive && this.state !== STATE_HURT && hitCounter(this.flashSteps) === 0
  }

  setState (state) {
    this.state = state
    this.steps = 0
  }

  getBox () {
    return inset(this.x, this.y, this.width, this.height, BODY_INSET)
  }

  // Where the enemy can go: free ground by default
  canStandAt (map, x, y) {
    return isFree(map, x, y)
  }

  // After the cloud
  start (map) {}

  // The image of its cloud: 3 of 8 frames; with a cloud of its own length (a room: see enemy.js, ROOM_CLOUD), the last
  // two last 6 frames ($FA0C), the first one the rest
  get cloudImage () {
    if (this.cloudSteps === undefined) {
      return Math.floor(this.steps / CLOUD_FRAME_STEPS)
    }
    const left = this.cloudSteps - this.steps
    return left > 2 * ROOM_CLOUD_FRAMES ? 0 : left > ROOM_CLOUD_FRAMES ? 1 : 2
  }

  knockBack (map) {
    if (this.steps <= KNOCKBACK_WAIT) {
      return
    }
    const direction = this.knockbackDirection
    const [dx, dy] = DIRECTION_VECTORS[direction]
    for (let i = 0; i < KNOCKBACK_SPEED; i++) {
      const onGrid = dx !== 0 ? (this.x - map.x) % TILE_WIDTH === 0 : (this.y - map.y) % TILE_HEIGHT === 0
      if ((onGrid && !canWalkTo(map, this.x, this.y, direction)) || !isInside(map, this.x + dx, this.y + dy, this.width, this.height)) {
        break
      }
      this.x += dx
      this.y += dy
    }
  }

  // By the sword of Link by default, or by something else (a bomb): its damage, the way it pushes
  hit (link, { damage, direction, byBomb } = {}) {
    if (damage === undefined) {
      this.lastSwing = link.swordSwing
    }
    this.life -= damage ?? link.swordDamage
    if (this.life <= 0) {
      soundManager.play(resource.getSound(SOUND_ENNEMY_DIE))
      this.drop = chooseDrop(this.type, link.killRecord, this.random, byBomb, this.slot)
      this.setState(STATE_DYING)
      return
    }
    soundManager.play(resource.getSound(SOUND_ENNEMY_HIT))
    this.flashSteps = FLASH_STEPS
    this.flashType = link.map?.type
    this.knockbackDirection = direction ?? link.direction
    this.resumeState = this.state
    this.setState(STATE_HURT)
  }

  // The states every enemy has; false for the others (the enemy's own)
  processCommon (map) {
    switch (this.state) {
      case STATE_SPAWNING:
        if (this.steps >= (this.cloudSteps ?? 3 * CLOUD_FRAME_STEPS)) {
          this.start(map)
        }
        return true
      case STATE_HURT:
        this.knockBack(map)
        if (this.steps >= KNOCKBACK_STEPS) {
          this.setState(this.resumeState)
        }
        return true
      case STATE_DYING:
        if (this.steps >= 3 * DEATH_FRAME_STEPS) {
          this.setState(STATE_DEAD)
          if (this.drop) {
            map.drops.push(new Drop(this.drop, this.x, this.y, this.random))
          }
        }
        return true
      case STATE_DEAD:
        return true
    }
    return false
  }

  act (map, link) {}

  // It hurt Link by touching him: in the ROM, the walkers and the leevers go back then (measured on an octorok)
  turnBack () {}

  // Reached by the sword or the wand Link holds out (see Link.getBlade), once a thrust
  isHitByBlade (link) {
    const blade = link.getBlade()
    if (!blade || !this.isVulnerable || (!blade.wand && link.swordSwing === this.lastSwing)) {
      return false
    }
    return reaches(this, ...bladeCentre(blade.x, blade.y, link.direction), blade.vertical ? REACH_BLADE_VERTICAL : REACH_BLADE_SIDEWAYS)
  }

  // By the sword, or by the wand (as hard as the white sword)
  hitByBlade (link) {
    this.hit(link, link.getBlade().wand ? { damage: WAND_DAMAGE, weapon: WEAPON_WAND } : undefined)
  }

  // The sword first: a hit enemy does not hurt Link in the same step. Under the clock, it is harmless
  fight (map, link) {
    if (this.isHitByBlade(link)) {
      this.hitByBlade(link)
      return
    }
    if (this.isActive && !map.frozen && overlaps(this.getBox(), link.getContactBox()) && link.hurt(this.contactDamage, this.getBox())) {
      this.turnBack()
    }
  }

  // Hit by a boomerang of Link: it stands still a while, and hurts Link all the same
  stun (link) {
    this.stunSteps = STUN_STEPS
  }

  process (map, link) {
    this.steps++
    if (this.flashSteps > 0) {
      this.flashSteps--
    }
    const stunned = this.stunSteps > 0
    if (stunned) {
      this.stunSteps--
    }
    // Standing still under the clock, or stunned
    if (!this.processCommon(map) && !map.frozen && !stunned) {
      this.act(map, link)
    }
    this.fight(map, link)
  }

  drawBody (context) {}

  draw (context) {
    switch (this.state) {
      case STATE_WAITING:
      case STATE_DEAD:
        return
      case STATE_SPAWNING:
        drawImage(context, resource.getSprite('misc_bomb_blow'), this.cloudImage, this.x, this.y, this.width, this.height)
        return
      case STATE_DYING:
        drawImage(context, resource.getSprite('death'), Math.floor(this.steps / DEATH_FRAME_STEPS), this.x, this.y, this.width, this.height)
        return
    }
    // Hit, in the palettes of the ROM (see flashColours)
    flashing = flashColours(this.flashSteps, this.flashType)
    this.drawBody(context)
    flashing = undefined
  }
}
