'use strict'

import soundManager from '../../service/sound-manager'
import resource from '../../resource'
import { NES_PIXEL, SOUND_REFILL_LOOP } from '../../constant'
import { Enemy } from './common'
import { heartRefill } from '../refill'

// The fairy of a pond of the surface, read in the ROM (object $2F of 9,3 and 3,4, bank 4 $8D90) and measured at 9,3.
// It flutters over the pond at x $78, y $7D (tiles $50 and $52, 4 frames each). The frame Link is at y $AD, x $70 to
// $80 ($AD = 1), he stands still and can do nothing ($AC = $40, the buttons cleared), and his hearts fill up ($63,
// see refill.js); from the next frame, hearts go round the pond. The frame after his life is full, they stand still,
// then go on 71 frames ($29 = $47); the last one, he is let go ($AD = 3, $AC = 0), and they are gone after it:
// nothing more until he comes back on the screen.
// The hearts (slots 2 to 9, tile $F3): the first one comes the frame after Link, 28 NES pixels above the fairy, its
// angle at $18 of 32; each next one when the angle of the first one is at $14, $10, $0C, $08, $04, $00, $1C ($8DE3).
// Every frame, the angle goes down by $60 / 256 ($B459), and each heart moves along it ($B3BD): x by the sine of the
// angle ($B3AD, 16 steps of a quarter turn) / 4 × $20, y by its cosine, in 256ths of a NES pixel
const NES_TOP = 0x3d
const PLACE = { x: 0x78, y: 0x7d }
const LINK_Y = 0xad
const LINK_MIN_X = 0x70
const LINK_MAX_X = 0x80
const IMAGE_FRAMES = 4
const HEARTS = 8
const HEART_ABOVE = 0x1c
const HEART_START_ANGLE = 0x18
const HEART_ANGLES = [0x14, 0x10, 0x0c, 0x08, 0x04, 0x00, 0x1c]
const ANGLE_STEP = 0x60
const SINES = [0x00, 0x18, 0x30, 0x47, 0x5a, 0x6a, 0x76, 0x7d, 0x80, 0x7d, 0x76, 0x6a, 0x5a, 0x47, 0x30, 0x18]
const RADIUS = 0x20
const AFTER_FULL = 0x47
// The steps of the fairy: waiting for Link, filling his hearts, the hearts going round, done
const WAITING = 0
const FILLING = 1
const AFTER = 2
const DONE = 3

// The move of a heart along one axis ($B43A: the 6 high bits of the sine times the radius)
const move = sine => (sine >> 2) * RADIUS

// A heart: its place and its angle in 256ths ($70 + slot / $0412, $84 / $041F, $0394 / $0380)
function createHeart () {
  return { x: PLACE.x << 8, y: (PLACE.y - HEART_ABOVE) << 8, angle: HEART_START_ANGLE << 8 }
}

// One frame of a heart ($8E1B)
export function moveHeart (heart) {
  heart.angle = (heart.angle - ANGLE_STEP) & 0x1fff
  const angle = heart.angle >> 8
  const dx = move(SINES[angle & 15])
  heart.x = (heart.x + ((angle & 0x18) >= 0x10 ? -dx : dx)) & 0xffff
  const dy = move(SINES[(angle + 8) & 15])
  heart.y = (heart.y + (((angle - 8) & 0x18) >= 0x10 ? -dy : dy)) & 0xffff
}

export class PondFairy extends Enemy {
  constructor (type, map, random = Math.random) {
    super(type, map.x + PLACE.x * NES_PIXEL, map.y + (PLACE.y - NES_TOP) * NES_PIXEL, { life: 0, contactDamage: 0 }, random)
    this.map = map
    this.uncounted = true
    this.step = WAITING
    this.frames = 0
    this.hearts = []
    this.refill = undefined
    this.wait = 0
    this.doneFrame = undefined
  }

  get mustDie () {
    return false
  }

  get isVulnerable () {
    return false
  }

  stun () {}

  // Link where the fairy waits for him (NES pixels)
  isLinkAtPond (link) {
    const x = Math.round((link.x - this.map.x) / NES_PIXEL)
    const y = Math.round((link.y - this.map.y) / NES_PIXEL) + NES_TOP
    return y === LINK_Y && x >= LINK_MIN_X && x <= LINK_MAX_X
  }

  process (map, link) {
    this.map = map
    this.frames++
    switch (this.step) {
      case WAITING:
        if (this.isLinkAtPond(link)) {
          this.step = FILLING
          this.hold(link)
          this.refill = heartRefill(link)
          soundManager.play(resource.getSound(SOUND_REFILL_LOOP))
          this.refill.step()
        }
        return
      case FILLING:
        // Full: the hearts stand still that frame ($8DBA leaves A at $47)
        if (this.refill.full) {
          this.step = AFTER
          this.wait = AFTER_FULL
          soundManager.stop(resource.getSound(SOUND_REFILL_LOOP))
          return
        }
        this.moveHearts()
        this.refill.step()
        return
      case AFTER:
        this.wait--
        this.moveHearts()
        if (this.wait === 0) {
          this.step = DONE
          this.doneFrame = this.frames
          this.release(link)
        }
    }
  }

  // Link stands still, his actions dropped
  hold (link) {
    link.atPond = this
    link.knockback = undefined
    link.stopWalking()
  }

  release (link) {
    if (link.atPond === this) {
      link.atPond = undefined
    }
  }

  // The hearts in the order of their slots: the first one leads, the next ones come after it ($8DEA)
  moveHearts () {
    if (this.hearts.length === 0) {
      this.hearts.push(createHeart())
    }
    for (let k = 0; k < HEARTS; k++) {
      if (!this.hearts[k]) {
        if ((this.hearts[0].angle >> 8) !== HEART_ANGLES[k - 1]) {
          continue
        }
        this.hearts[k] = createHeart()
      }
      moveHeart(this.hearts[k])
    }
  }

  // Their places (NES pixels) while they go round, and the frame Link is let go
  get heartPlaces () {
    if (this.step === WAITING || (this.step === DONE && this.frames !== this.doneFrame)) {
      return []
    }
    return this.hearts.filter(Boolean).map(heart => ({ x: heart.x >> 8, y: heart.y >> 8 }))
  }

  draw (context) {
    const fairy = resource.getSprite('item_fairy')
    fairy?.images[Math.floor(this.frames / IMAGE_FRAMES) % 2]?.draw(context, this.x, this.y, this.width, this.height)
    // A heart is the 8 pixels of the tile $F3 at its place (the sprite puts them 4 pixels in and 1 down)
    const heart = resource.getSprite('item_heart')?.images[0]
    for (const place of this.heartPlaces) {
      heart?.draw(context, this.map.x + (place.x - 4) * NES_PIXEL, this.map.y + (place.y - 1 - NES_TOP) * NES_PIXEL, this.width, this.height)
    }
  }
}
